// swift-tools-version: 6.2
import PackageDescription

// NibbleKit holds all of Nibble's code. The macOS app target (App/, generated by XcodeGen from
// project.yml) is only the composition root that wires these modules together.
//
// Dependency rule: every module depends on NibbleCore and nothing else in the package.
// Only the app target sees more than one module.
let package = Package(
    name: "NibbleKit",
    defaultLocalization: "en",
    platforms: [.macOS(.v26)],
    products: [
        .library(name: "NibbleCore", targets: ["NibbleCore"]),
        .library(name: "NibbleBackends", targets: ["NibbleBackends"]),
        .library(name: "NibbleStore", targets: ["NibbleStore"]),
        .library(name: "NibbleSystem", targets: ["NibbleSystem"]),
        .library(name: "NibbleUI", targets: ["NibbleUI"]),
    ],
    targets: [
        // Domain model and application logic. Foundation only: no AppKit, no I/O.
        .target(name: "NibbleCore"),
        // Chat backends (Hermes, OpenAI-compatible, ...) behind NibbleCore.ChatBackend.
        .target(name: "NibbleBackends", dependencies: ["NibbleCore"]),
        // Everything Nibble writes to disk: user data, settings, retention.
        .target(name: "NibbleStore", dependencies: ["NibbleCore"]),
        // macOS services without UI: global hotkey, screen capture, launch at login.
        .target(name: "NibbleSystem", dependencies: ["NibbleCore"]),
        // Windows and views: the floating panel, the status item, the chat surface.
        .target(
            name: "NibbleUI",
            dependencies: ["NibbleCore"],
            resources: [.process("Resources")]
        ),
        .testTarget(name: "NibbleCoreTests", dependencies: ["NibbleCore"]),
        .testTarget(name: "NibbleStoreTests", dependencies: ["NibbleStore"]),
        .testTarget(name: "NibbleBackendsTests", dependencies: ["NibbleBackends"]),
        .testTarget(name: "NibbleSystemTests", dependencies: ["NibbleSystem"]),
        .testTarget(name: "NibbleUITests", dependencies: ["NibbleUI"]),
    ]
)
